def parse_row(line: str) -> list[str]:
    result = []
    current = []
    in_quotes = False
    for char in line:
        if char == '"':
            in_quotes = not in_quotes
            current.append(char)
        elif in_quotes:
            current.append(char)
        else:
            if char == ',':
                result.append(''.join(current))
                current = []
            else:
                current.append(char)
    if current:
        result.append(''.join(current))
    return result
