def delays(n: int, base: float = 1.0, cap: float = 30.0) -> list[float]:
    if n <= 0:
        return []
    delays = []
    for i in range(1, n + 1):
        delay = base * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays
