from collections import OrderedDict

def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = OrderedDict()
    for row in rows:
        if key not in row:
            seen[row] = row
        else:
            if key in seen:
                # Keep the first occurrence
                del seen[key]
            else:
                seen[key] = row
    return list(seen.values())
```

