def parse_money(s: str) -> float | None:
    if not s:
        return None
    # Remove leading '$'
    s = s.strip()
    if s.startswith('$'):
        s = s[1:].strip()
    # Remove thousands separators (e.g., ',')
    s = s.replace(',', '')
    # Remove any remaining whitespace
    s = s.strip()
    try:
        return float(s)
    except ValueError:
        return None
